            "while True:\n    all_ready = True\n    while get_pos_x() > 0:\n        move(West)\n    while get_pos_y() > 0:\n        move(South)\n    for row in range(get_world_height()):\n        for col in range(get_world_width()):\n            if get_ground_type() != Grounds.Soil:\n                till()\n            if get_entity_type() == None or get_entity_type() == Entities.Dead_Pumpkin:\n                plant(Entities.Pumpkin)\n            if get_entity_type() != Entities.Pumpkin or not can_harvest():\n                all_ready = False\n            if col + 1 < get_world_width():\n                move(East)\n        for col in range(get_world_width() - 1):\n            move(West)\n        if row + 1 < get_world_height():\n            move(North)\n    for row in range(get_world_height() - 1):\n        move(South)\n    if all_ready:\n        harvest()",
            "# Requires a mature cactus rectangle. Sort east and north independently.\nfor sweep in range(max(get_world_width(), get_world_height())):\n    while get_pos_x() > 0:\n        move(West)\n    while get_pos_y() > 0:\n        move(South)\n    for row in range(get_world_height()):\n        for col in range(get_world_width()):\n            if get_pos_x() + 1 < get_world_width():\n                if measure() > measure(East):\n                    swap(East)\n            if get_pos_y() + 1 < get_world_height():\n                if measure() > measure(North):\n                    swap(North)\n            if col + 1 < get_world_width():\n                move(East)\n        for col in range(get_world_width() - 1):\n            move(West)\n        if row + 1 < get_world_height():\n            move(North)\n    for row in range(get_world_height() - 1):\n        move(South)\nharvest()",
            "# Generate a maze from a bush first. Explore using a stack.\ndirections = [North, East, South, West]\ndef reverse(direction):\n    return directions[(directions.index(direction)+2)%4]\nvisited = set()\npath = []\nwhile get_entity_type() != Entities.Treasure:\n    visited.add((get_pos_x(),get_pos_y()))\n    advanced = False\n    for direction in directions:\n        if can_move(direction):\n            move(direction)\n            position = (get_pos_x(),get_pos_y())\n            if position not in visited:\n                path.append(direction)\n                advanced = True\n                break\n            move(reverse(direction))\n    if not advanced:\n        if len(path) == 0:\n            break\n        move(reverse(path.pop()))\nif get_entity_type() == Entities.Treasure:\n    harvest()",
